// <diletta-data-column-header> — a INSTÂNCIA WEB de `design-system-data-column-header`.
//
// No Figma é UM conjunto remoto (`web-title-list-cell`, 284 usos), com `Sorting` e
// `State`. O comentário antigo dizia "dezessete componentes em dois nomes": era o nome
// das camadas, que o Figma numera ao duplicar. Aqui o porte é atributo, e a DIREÇÃO
// também — `Ascending`/`Descending` de lá são `direcao=asc|desc` daqui.
const PORTE = { regular: 24, compacto: 20 };
const ORDENACAO = ['nenhuma', 'ordenavelInativa', 'ordenavelAtiva'];

const SETA = (dir) =>
  `<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" class="ordem"
     style="transform: rotate(${dir === 'desc' ? 180 : 0}deg)">
     <path d="M8 12V4M4.5 7.5L8 4l3.5 3.5" stroke="currentColor" stroke-width="1.5"
       fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

class DilettaDataColumnHeader extends HTMLElement {
  static observedAttributes = ['porte', 'ordenacao', 'direcao', 'rotulo', 'alinhamento'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.addEventListener('click', () => this.aciona());
    this.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.aciona(); }
    });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get ordenacao() {
    const v = this.getAttribute('ordenacao');
    return ORDENACAO.includes(v) ? v : 'nenhuma';
  }

  aciona() {
    if (this.ordenacao === 'nenhuma') return;
    const dir = this.getAttribute('direcao') === 'asc' ? 'desc' : 'asc';
    this.dispatchEvent(new CustomEvent('ordenar', { detail: { direcao: dir }, bubbles: true }));
  }

  render() {
    const porte = PORTE[this.getAttribute('porte')] ? this.getAttribute('porte') : 'regular';
    const ord = this.ordenacao;
    const dir = this.getAttribute('direcao') === 'desc' ? 'desc' : 'asc';
    const rotulo = this.getAttribute('rotulo') || '';
    const fim = this.getAttribute('alinhamento') === 'fim';

    // 4.1.2 / 1.3.1: coluna ordenada anuncia a DIREÇÃO, e a que só aceita ordem
    // anuncia `none`. Sem isso o leitor de tela ouve um cabeçalho e não sabe que
    // ele é acionável nem qual ordem está valendo.
    const aria = ord === 'ordenavelAtiva' ? (dir === 'asc' ? 'ascending' : 'descending')
      : ord === 'ordenavelInativa' ? 'none' : null;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .cabeca {
          box-sizing: border-box;
          height: ${PORTE[porte]}px;
          display: flex; align-items: center; gap: 4px;
          justify-content: ${fim ? 'flex-end' : 'flex-start'};
          color: var(--cps-textSecondary);
          font-size: var(--cps-type-caption-size, 12px);
          cursor: ${ord === 'nenhuma' ? 'default' : 'pointer'};
        }
        .ordem { width: 12px; height: 12px; flex: none; }
        /* Inativa mostra que ACEITA ordem sem afirmar direção. Duas variantes não
           bastariam: a coluna ordenável em repouso precisa se distinguir tanto da
           que não ordena quanto da que está ordenada. */
        .cabeca[data-ordem="ordenavelInativa"] .ordem { opacity: .4; }
        .cabeca:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <div class="cabeca" part="cabeca" data-ordem="${ord}"
           role="columnheader" ${aria ? `aria-sort="${aria}"` : ''}
           tabindex="${ord === 'nenhuma' ? -1 : 0}">
        <span class="rotulo">${rotulo}</span>${ord === 'nenhuma' ? '' : SETA(dir)}
      </div>`;
  }
}

customElements.define('diletta-data-column-header', DilettaDataColumnHeader);
export { DilettaDataColumnHeader, PORTE };
